    * (404) POST:/WebGoat/WebWolf/mail/send
    * Found 1 potential fault of type-code 200
    */
    @Test @Timeout(60)
    fun test_196_postOnSendReturnsMismatchResponseWithSchema()  {
        
        val cookies_userB : Map<String,String> = given()
            .contentType("application/x-www-form-urlencoded")
            .body("username=userbb&password=userBB")
            .post("${baseUrlOfSut}/WebGoat/login")
            .then().extract().cookies()
            
        
        // Fault200. Schema Violation: Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.status.unknown Response status 404 not defined for path '/WebWolf/mail/send'.
        given().accept("*/*")
                .cookies(cookies_userB)
                .noContentType()
                .post("${baseUrlOfSut}/WebGoat/WebWolf/mail/send?email=zAaTGiBeVGM2Pn")
                .then()
                .statusCode(404)
                .assertThat()
                .contentType("application/json")
                .body("'status'", numberMatches(404))
                .body("'error'", containsString("Not Found"))
                .body("'path'", containsString("/WebGoat/WebWolf/mail/send"))
    }
    
    
